const oyentes = [];
const guardado = () => { try { return localStorage.getItem("phy-lang"); } catch { return null; } };
let lang = ["es", "en"].includes(guardado()) ? guardado() : (navigator.language ?? "es").toLowerCase().startsWith("en") ? "en" : "es";

export const getLang = () => lang;
export const locale = () => (lang === "en" ? "en-US" : "es-CR");
export function t(clave, p) {
  let s = D[lang][clave] ?? D.es[clave] ?? clave;
  if (p) s = s.replace(/\{(\w+)\}/g, (_, k) => (p[k] ?? ""));
  return s;
}
export const onLang = (f) => oyentes.push(f);
export const CLAVES = D; // para pruebas

// Aplica el idioma a los elementos estáticos del HTML: data-i (texto) y data-ia ("atributo:clave;atributo:clave").
export function aplicar() {
  document.documentElement.lang = lang;
  document.querySelectorAll("[data-i]").forEach((e) => { e.textContent = t(e.dataset.i); });
  document.querySelectorAll("[data-ia]").forEach((e) => { for (const par of e.dataset.ia.split(";")) { const [a, k] = par.split(":"); e.setAttribute(a, t(k)); } });
  document.title = t("doc.title");
  document.querySelector('meta[name="description"]')?.setAttribute("content", t("doc.desc"));
  document.querySelectorAll(".idioma button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.lang === lang)));
  document.querySelector(".idioma")?.setAttribute("data-activo", lang);
}
export function setLang(l) {
  if (l === lang || !D[l]) return;
  lang = l;
  try { localStorage.setItem("phy-lang", l); } catch { /* sin almacenamiento */ }
  aplicar();
  oyentes.forEach((f) => f(l));
}
